const amqplib = require('amqplib');

/**
 * Publishes a batch of messages to a RabbitMQ exchange with publisher-confirm
 * durability: the broker must acknowledge each message before we're sure
 * it was durably stored.
 *
 * @param {import('amqplib').Connection} connection - an open AMQP connection, one network hop from this worker
 * @param {string} exchange - the exchange to publish to
 * @param {string} routingKey - the routing key for each message
 * @param {string[]} messages - the batch of N message payloads to publish
 * @returns {Promise<void>} resolves once every message in the batch has been confirmed
 */
async function publishBatch(connection, exchange, routingKey, messages) {
  // Confirm channel: enables publisher confirms so the broker acks/nacks each publish.
  const channel = await connection.createConfirmChannel();

  for (const message of messages) {
    channel.publish(exchange, routingKey, Buffer.from(message));
    // Wait for THIS message's confirm before the loop moves on to the next publish.
    await channel.waitForConfirms();
  }

  await channel.close();
}

module.exports = { publishBatch };
